report={'status':'running','host':host_state(),'head':subprocess.check_output(['git','rev-parse','HEAD']).decode().strip(),'cases':[]}
llm=LLM(str(DEFAULT_MODEL),backend='hip_gfx1151',quant='gguf_ud_q4_k_xl',execution_profile='production',max_sequence_length=8192,max_active_requests=1,prefix_cache='off');provider=None
try:
 provider=Qwen4ExpMTPTextProvider(target_generator=llm._get_text_generator(),config=SpeculativeProviderConfig('qwen4_exp_mtp',str(DEFAULT_SIDECAR),3))
 d=provider.draft
 def state():
  data={}
  for name,b in [('hidden',d.last_hidden),('key',d.attention.key_cache),('value',d.attention.value_cache)]:
   a=np.empty(b.nbytes,np.uint8);copy_device_to_host(host_array_ptr(a),b,runtime=d.runtime);data[name]=hashlib.sha256(a.tobytes()).hexdigest()
  return {'position':d.position,**data}
 for count in (1,2,3,4):
  hidden=np.random.default_rng(count).standard_normal(d.config.residual_width).astype(np.float32)
  tokens=(100,200,300,400)[:count];root=99
  states=[]
  for arm in ('neural_head','lookup'):
   d.reset()
   if arm=='lookup':d.propose_lookup_chain(start_token=root,target_hidden_seed=hidden,candidates=tokens)
   else:
    for i,t in enumerate((root,*tokens[:-1])):
     d.forward(t,hidden if i==0 else None,capture_logits=False,capture_hidden_seed=False,capture_token_id=False,hidden_seed_resident=i>0)
   states.append(state())
  report['cases'].append({'count':count,'states':states,'exact_equal':states[0]==states[1]});assert states[0]==states[1]
 report['status']='passed'
except BaseException as e:report['status']='failed';report['error']=repr(e);raise
